@Cacheable(cacheNames = "books", key = "#isbn")
Book findBook(ISBN isbn) { return store.find(isbn); }        // miss: invoke + populate

@CacheEvict(cacheNames = "books", key = "#book.isbn")
void updateBook(Book book) { store.save(book); }             // store commit, then evict

