private final ConcurrentHashMap<String, Entry> map = new ConcurrentHashMap<>();

Entity read(String id) {
    Entry e = map.computeIfAbsent(id, k -> new Entry(store.find(k), deadline()));
    return e.isExpired() ? refresh(id) : e.value();   // TTL is application code
}
void update(Entity e) { store.save(e); map.remove(e.id()); }
